        h.Tasks:Release(self.Name)
        h.Navigator:Cancel(self.Name)
        self.Status = "Waiting"
        return
    end
    if
        self.Target
        and (
            (self.Options.Filter and not self.Options.Filter(self.Target))
            or (self.Options.Radius() > 0 and h.Adapter:Distance(self.Target) > self.Options.Radius())
