        self:Step()
    end, function()
        self:Stop()
    end)
end
function Worker:Stop()
    self.Running, self.Target, self.Status = false, nil, "Disabled"
    self.H.Scheduler:Remove(self.Name)
    self.H.Tasks:Release(self.Name)
    self.H.Navigator:Cancel(self.Name)
end
Worker.Destroy = Worker.Stop
return Worker
